    banned_at timestamp with time zone,
    ban_reason text,
    deleted_at timestamp with time zone,
    personal_shards integer DEFAULT 0 NOT NULL,
    preshards integer DEFAULT 0 NOT NULL,
    subscription_tier public.subscription_tier DEFAULT 'free'::public.subscription_tier NOT NULL,
    subscription_expires_at timestamp with time zone,
    notification_preferences jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    interest_tags text[] DEFAULT '{}'::text[] NOT NULL,
    discovery_opt_in boolean DEFAULT false NOT NULL,
    read_receipts_enabled boolean DEFAULT true NOT NULL,
    profile_public boolean DEFAULT false NOT NULL
);

