-- Name: check_signup_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_signup_email(p_email text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_profile_created boolean;
BEGIN
  SELECT profile_created INTO v_profile_created
  FROM public.signup_tracker
  WHERE email = p_email;

  IF NOT FOUND THEN
    RETURN 'signup';
  END IF;

  IF v_profile_created THEN
    RETURN 'exists';
  END IF;

  DELETE FROM public.signup_tracker
  WHERE email = p_email AND NOT profile_created;

  RETURN 'signup';
END;
$$;


